3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Monster Walk</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	
14	    :root {
15	      /* Sprite sheet monster-walk.png: 23 frames of 276 × 300 px, transparent.
16	         Source: one gait cycle from the 24 fps video, cut out and aligned to a
17	         shared ground line and body axis. The vertical bob lives in the frames
18	         themselves – no artificial bounce needed in CSS. */
19	      --frame-w: 184px;                        /* display width of a single frame */
20	      --frame-h: 200px;                        /* 300/276 × 184 → keeps the aspect ratio */
21	      --sheet-w: calc(var(--frame-w) * 23);    /* 4232px – must match steps(23) */
22	      --ground: 90px;                          /* height of the ground strip */
23	      --cycle: 0.96s;                          /* 23 frames at 24 fps = original tempo */
24	      /* Stride: the distance covered by one full gait cycle. This is what sets the
25	         walking speed – too large and the feet slide across the ground. Smaller =
26	         slower and more mincing, larger = faster and more slippery. */
27	      --stride: 130px;
28	      --crossing: 16s;                         /* fallback; the script below derives it from --stride */
29	    }
30	
31	    body {
32	      min-height: 100vh;
33	      background: linear-gradient(#dff0f7, #eef8fb 70%);
34	      overflow: hidden;
35	      position: relative;
36	    }
37	
38	    .ground {
39	      position: absolute;
40	      inset: auto 0 0 0;
41	      height: var(--ground);
42	      background: #cfe6c9;
43	      border-top: 3px solid #a9cfa0;
44	    }
45	
46	    /* The wrapper handles the travel across the screen … */
47	    .walker {
48	      position: absolute;
49	      left: 0;
50	      bottom: calc(var(--ground) - 3px);      /* feet rest on the edge of the ground */
51	      width: var(--frame-w);
52	      height: var(--frame-h);
53	      animation: move-across var(--crossing) linear 1 forwards;
54	    }
55	
56	    /* The shadow sits under the leading foot, not under the tail.
57	       The monster walks right → left, so it belongs on the right-hand side. */
58	    .shadow {
59	      position: absolute;
60	      right: 8%;
61	      width: 42%;
62	      bottom: 0;
63	      height: 11px;
64	      background: rgba(60, 80, 60, 0.22);
65	      border-radius: 50%;
66	      filter: blur(3px);
67	    }
68	
69	    /* … the sprite only flips through the frames. */
70	    .monster {
71	      position: absolute;
72	      inset: 0;
73	      background-image: url("monster-walk.png");
74	      background-repeat: no-repeat;
75	      background-size: var(--sheet-w) var(--frame-h);
76	      /*transform: scaleX(-1);*/               /* mirror the sprite: monster faces left */
77	      animation: walk-cycle var(--cycle) steps(23) infinite;
78	    }
79	
80	    /* Flips through all 23 frames */
81	    @keyframes walk-cycle {
82	      from { background-position: 0 0; }
83	      to   { background-position: calc(-1 * var(--sheet-w)) 0; }
84	    }
85	
86	    /* Walks once from the right edge all the way out of frame */
87	    @keyframes move-across {
88	      from { transform: translateX(100vw); }
89	      to   { transform: translateX(calc(-1 * var(--frame-w))); }
90	    }
91	
92	    @media (prefers-reduced-motion: reduce) {
93	      .walker { animation: none; transform: translateX(40vw); }
94	      .monster { animation: none; }
95	    }
96	  </style>
97	  <script>
98	    /* The distance to walk depends on the window width, the gait tempo does not.
99	       With a fixed duration the monster would move faster on wide monitors and its
100	       feet would slide. So the duration is derived from the stride instead: a whole
101	       number of gait cycles, each one --cycle long and --stride wide. */
102	    (() => {
103	      const root = document.documentElement;
104	      const px = (name) => parseFloat(getComputedStyle(root).getPropertyValue(name));
