// Throwaway CDP driver: load the site, press Alt+A, screenshot mid-walk.
import { writeFileSync } from 'node:fs';

const SITE = process.argv[2];
const OUT = process.argv[3];

const wait = (ms) => new Promise((r) => setTimeout(r, ms));

const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find((t) => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));

let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
};
const send = (method, params = {}) =>
  new Promise((res) => {
    const myId = ++id;
    pending.set(myId, res);
    ws.send(JSON.stringify({ id: myId, method, params }));
  });

await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: SITE });
await wait(1500);

const before = await send('Runtime.evaluate', {
  expression: 'document.querySelectorAll(".monster-walk").length',
  returnByValue: true,
});
console.log('monsters before Alt+A:', before.result.result.value);

// Alt+A — modifier bit 1 = Alt
for (const type of ['keyDown', 'keyUp']) {
  await send('Input.dispatchKeyEvent', {
    type: type === 'keyDown' ? 'keyDown' : 'keyUp',
    modifiers: 1,
    key: 'a',
    code: 'KeyA',
    windowsVirtualKeyCode: 65,
    nativeVirtualKeyCode: 65,
  });
}
await wait(600);

const state = await send('Runtime.evaluate', {
  expression: `(() => {
    const w = document.querySelector('.monster-walk');
    if (!w) return { found: false };
    const s = getComputedStyle(w);
    const sprite = getComputedStyle(w.querySelector('.sprite'));
    return {
      found: true,
      crossing: s.getPropertyValue('--crossing').trim(),
      animation: s.animationName + ' ' + s.animationDuration,
      spriteAnim: sprite.animationName + ' ' + sprite.animationDuration,
      bg: sprite.backgroundImage,
      bgSize: sprite.backgroundSize,
      transform: sprite.transform,
      rect: w.getBoundingClientRect().toJSON(),
    };
  })()`,
  returnByValue: true,
});
console.log('state after Alt+A:', JSON.stringify(state.result.result.value, null, 2));

// Confirm the sprite sheet actually loaded (not a broken URL).
const img = await send('Runtime.evaluate', {
  expression: `new Promise((res) => {
    const i = new Image();
    i.onload = () => res(i.naturalWidth + 'x' + i.naturalHeight);
    i.onerror = () => res('LOAD ERROR');
    i.src = 'assets/monster-walk.png';
  })`,
  awaitPromise: true,
  returnByValue: true,
});
console.log('sprite sheet:', img.result.result.value);

// Double press while walking must not stack a second monster.
for (const type of ['keyDown', 'keyUp']) {
  await send('Input.dispatchKeyEvent', {
    type,
    modifiers: 1,
    key: 'a',
    code: 'KeyA',
    windowsVirtualKeyCode: 65,
    nativeVirtualKeyCode: 65,
  });
}
const dbl = await send('Runtime.evaluate', {
  expression: 'document.querySelectorAll(".monster-walk").length',
  returnByValue: true,
});
console.log('monsters after second Alt+A:', dbl.result.result.value);

await wait(1200);
const shot = await send('Page.captureScreenshot', { format: 'png' });
writeFileSync(OUT, Buffer.from(shot.result.data, 'base64'));

// Position over time proves it is actually travelling left → right.
const x1 = await send('Runtime.evaluate', {
  expression: 'document.querySelector(".monster-walk")?.getBoundingClientRect().x ?? null',
  returnByValue: true,
});
await wait(1500);
const x2 = await send('Runtime.evaluate', {
  expression: 'document.querySelector(".monster-walk")?.getBoundingClientRect().x ?? null',
  returnByValue: true,
});
console.log('x at t1:', x1.result.result.value, '-> x at t2:', x2.result.result.value);

ws.close();

