/* Walking monster easter egg (Alt+A) — Monster-Dev.
   Sprite sheet assets/monster-walk.png: 23 frames of 276 × 300 px, one full gait
   cycle. The vertical bob is already in the frames, so no bounce is needed here. */
.monster-walk {
  --frame-w: 184px;                        /* display width of a single frame */
  --frame-h: 200px;                        /* 300/276 × 184 → keeps the aspect ratio */
  --sheet-w: calc(var(--frame-w) * 23);    /* 4232px — must match steps(23) */
  --cycle: 0.96s;                          /* 23 frames at 24 fps = original tempo */
  /* Stride: the distance covered by one full gait cycle — this is what sets the
     walking speed. Smaller = slower and more mincing, larger = faster, until the
     feet start sliding across the ground. */
  --stride: 130px;
  --crossing: 16s;                         /* fallback; script.js derives it from --stride */

  position: fixed;
  left: 0;
  bottom: 0;
  z-index: 10;
  width: var(--frame-w);
  height: var(--frame-h);
  pointer-events: none;
  animation: monster-across var(--crossing) linear 1 forwards;
}

/* The shadow sits under the leading foot, not under the tail.
   The monster walks left → right, so it belongs on the left-hand side. */
.monster-walk .shadow {
  position: absolute;
  left: 8%;
  bottom: 0;
  width: 42%;
  height: 11px;
  background: rgba(60, 80, 60, 0.22);
  border-radius: 50%;
  filter: blur(3px);
}

/* The wrapper travels across the screen, the sprite only flips through the frames. */
.monster-walk .sprite {
  position: absolute;
  inset: 0;
  background-image: url("assets/monster-walk.png");
  background-repeat: no-repeat;
  background-size: var(--sheet-w) var(--frame-h);
  transform: scaleX(-1);                   /* mirror the sprite: monster faces right */
  animation: monster-cycle var(--cycle) steps(23) infinite;
}

/* Flips through all 23 frames */
@keyframes monster-cycle {
  from { background-position: 0 0; }
  to   { background-position: calc(-1 * var(--sheet-w)) 0; }
}

/* Walks once in from the left edge and all the way out of frame on the right */
@keyframes monster-across {
  from { transform: translateX(calc(-1 * var(--frame-w))); }
  to   { transform: translateX(100vw); }
}

@media (prefers-reduced-motion: reduce) {
  .monster-walk { animation: none; transform: translateX(40vw); }
  .monster-walk .sprite { animation: none; }
}
